def grid_of(g,comp):
    rs=sorted({x for x,y in comp}); cs=sorted({y for x,y in comp})
    return [[g[r][c] for c in cs] for r in rs]
def occurrences(big,small):
    H,W=len(big),len(big[0]); h,w=len(small),len(small[0]); res=[]
