def transform(grid):
    import copy
    g=[row[:] for row in grid]; H,W=len(g),len(g[0])
    seen=set(); shapes=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); comp=[]
                while q:
                    a,b=q.pop(); comp.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<H and 0<=y<W and g[x][y] and (x,y) not in seen:
                                seen.add((x,y)); q.append((x,y))
                rs=sorted({x for x,y in comp}); cs=sorted({y for x,y in comp})
                shapes.append((comp,[[g[r][c] for c in cs] for r in rs],(rs[0],rs[-1],cs[0],cs[-1])))
    def occ(big,small):
        Bh,Bw=len(big),len(big[0]); h,w=len(small),len(small[0]); n=0
        for r in range(Bh-h+1):
            for c in range(Bw-w+1):
                if all(big[r+i][c+j]==small[i][j] for i in range(h) for j in range(w)): n+=1
        return n
    to_del=[]
    for i,(comp,pat,bb) in enumerate(shapes):
        for j,(c2,p2,b2) in enumerate(shapes):
            if i!=j and b2!=bb and occ(p2,pat)>0:
                to_del.append(bb); break
    out=[row[:] for row in grid]
    for r0,r1,c0,c1 in to_del:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c]=0
    return out
